    def __init__(self, *, endpoint: "str", transport: "typing.Optional[TransportProtocol]" = _DEFAULT, tls: "TlsServerConfig", http2_only: "typing.Optional[bool]" = _DEFAULT, max_frame_size: "typing.Optional[int]" = _DEFAULT, max_concurrent_streams: "typing.Optional[int]" = _DEFAULT, max_header_list_size: "typing.Optional[int]" = _DEFAULT, read_buffer_size: "typing.Optional[int]" = _DEFAULT, write_buffer_size: "typing.Optional[int]" = _DEFAULT, keepalive: "typing.Optional[KeepaliveServerParameters]" = _DEFAULT, auth: "typing.Optional[ServerAuthenticationConfig]" = _DEFAULT, metadata: "typing.Optional[str]" = _DEFAULT):
        self.endpoint = endpoint
        if transport is _DEFAULT:
            self.transport = None
        else:
            self.transport = transport
        self.tls = tls
        if http2_only is _DEFAULT:
            self.http2_only = None
        else:
            self.http2_only = http2_only
        if max_frame_size is _DEFAULT:
            self.max_frame_size = None
        else:
            self.max_frame_size = max_frame_size
